(function(){
  var card=document.getElementById('mhCard');if(!card)return;
  var list=document.getElementById('mhList'),state=document.getElementById('mhState'),q=document.getElementById('mhQ'),hint=document.getElementById('mhHint'),again=document.getElementById('mhAgain'),conf=document.getElementById('mhConf');
  var cols=['#FF67A3','#9867FF','#58E1FF','#FFD167','#7FEB7F','#FF8A67'],reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  function burst(){if(reduce)return;conf.innerHTML='';for(var i=0;i<34;i++){var e=document.createElement('i'),a=Math.random()*Math.PI*2,d=90+Math.random()*190;
    e.style.cssText='background:'+cols[i%cols.length]+';--x:'+Math.cos(a)*d+'px;--y:'+(Math.sin(a)*d-40)+'px;--r:'+(Math.random()*720-360)+'deg;animation-delay:'+Math.random()*.08+'s';conf.appendChild(e)}}
  [].forEach.call(list.children,function(b){b.addEventListener('click',function(){
    if(card.classList.contains('done'))return;
    card.classList.add('done');b.classList.add('pick');
    [].forEach.call(list.children,function(x){x.querySelector('.mh-by').textContent=(x===b?'Your vote · ':'')+'picked by '+x.dataset.by});
    state.textContent='Revealed';q.textContent=b.dataset.by+' picked that one.';hint.textContent='Nobody knew until now. That is the whole game.';
    again.hidden=false;burst();
  })});
  again.addEventListener('click',function(){
    card.classList.remove('done');[].forEach.call(list.children,function(x){x.classList.remove('pick');x.querySelector('.mh-by').textContent=''});
    state.textContent='Blind vote';q.textContent='Which video wins tonight?';hint.textContent='No names shown. Judge the video, not the picker. Tap one.';again.hidden=true;
  });
})();

(function(){
  var T={c:2000,p:150,k:200,f:65},S={c:0,p:0,k:0,f:0},n=0,CIRC=326.7;
  var $=function(i){return document.getElementById(i)},mack=$('mackImg'),main=$('sayMain'),sub=$('saySub');
  var lines={start:['Nice start.','Mack is taking notes.','mack-thinking'],protein:['Protein is on track.','Keep that up.','mack-celebrating'],
    room:['Plenty of room in the stash.','Eat something good.','mack-logging'],close:['Now we are cooking.','Look at those bars go.','mack-success'],
    over:['Cheat day? Mack checked.','You are allowed.','mack-cheatday']};
  function render(){
    $('cal').textContent=S.c.toLocaleString();
    $('pr').style.strokeDashoffset=CIRC*(1-Math.min(S.c/T.c,1));
    [['p','pv','pb'],['k','cv','cb'],['f','fv','fb']].forEach(function(a){$(a[1]).textContent=S[a[0]];$(a[2]).style.width=Math.min(S[a[0]]/T[a[0]],1)*100+'%'});
  }
  function say(){
    if(!S.c){main.textContent="Mack's ready when you are.";sub.textContent='Tap a food below.';mack.src='img/3d/mack-logging.webp';return}
    var l=S.c>T.c?lines.over:S.p>=T.p*.9?lines.protein:S.c>T.c*.6?lines.close:n===1?lines.start:lines.room;
    main.textContent=l[0];sub.textContent=l[1];mack.src='img/3d/'+l[2]+'.webp';
    mack.classList.add('hop');setTimeout(function(){mack.classList.remove('hop')},320);
  }
  document.querySelectorAll('.food').forEach(function(b){b.addEventListener('click',function(){
    S.c+=+b.dataset.c;S.p+=+b.dataset.p;S.k+=+b.dataset.k;S.f+=+b.dataset.f;n++;render();say();
  })});
  $('reset').addEventListener('click',function(){S={c:0,p:0,k:0,f:0};n=0;render();say()});
  render();
  var st=$('stage');
  if('IntersectionObserver' in window){new IntersectionObserver(function(e,o){e.forEach(function(x){if(x.isIntersecting){st.classList.add('in');o.disconnect()}})},{threshold:.35}).observe(st)}else{st.classList.add('in')}
})();

(function(){
  var reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  var money=function(v){return '$'+v.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',')};
  var T=299.36,big=document.getElementById('big');
  var scene=document.getElementById('scene'),rows=[].slice.call(scene.querySelectorAll('.row')),
      steps=[].slice.call(scene.querySelectorAll('.step')),dots=[].slice.call(scene.querySelectorAll('.dots i')),
      left=document.getElementById('left');
  if(reduce){left.textContent='$0.00';left.classList.add('done');rows.forEach(function(r){r.classList.add('on')});return;}
  /* the hero number rolls up once on load */
  big.textContent='$0.00';
  var t0=null;
  requestAnimationFrame(function f(ts){
    if(!t0)t0=ts;var p=Math.min((ts-t0)/1500,1),e=p===1?1:1-Math.pow(2,-10*p);
    big.textContent=money(T*e);if(p<1)requestAnimationFrame(f);
  });
  /* the payday scene follows scroll */
  var cur=-1,queued=false;
  function update(){
    queued=false;
    var r=scene.getBoundingClientRect(),h=scene.offsetHeight-innerHeight,p=Math.max(0,Math.min(1,-r.top/h));
    var s=p<.2?0:p<.45?1:p<.72?2:3;
    var n=p<.3?0:p>=.72?3:Math.min(3,1+Math.floor((p-.3)/.14));
    var sum=0;
    rows.forEach(function(row,i){var on=i<n;row.classList.toggle('on',on);if(on)sum+=+row.dataset.v});
    left.textContent=money(Math.max(0,T-sum));left.classList.toggle('done',n===3);
    if(s!==cur){cur=s;steps.forEach(function(x,i){x.classList.toggle('on',i===s)});dots.forEach(function(x,i){x.classList.toggle('on',i===s)})}
  }
  function req(){if(!queued){queued=true;requestAnimationFrame(update)}}
  addEventListener('scroll',req,{passive:true});addEventListener('resize',req);update();
})();

(function(){
  var $=function(i){return document.getElementById(i)},opts=$('opts'),reveal=$('reveal'),verdict=$('verdict'),timer=$('timer'),bar=$('bar');
  var reduce=matchMedia('(prefers-reduced-motion: reduce)').matches,t=0,done=false,iv;
  function fmt(s){return Math.floor(s/60)+':'+('0'+(s%60)).slice(-2)}
  function run(){clearInterval(iv);t=0;timer.textContent='0:00';bar.style.transition='none';bar.style.transform='scaleX(1)';
    if(!reduce){void bar.offsetWidth;bar.style.transition='transform 41s linear';bar.style.transform='scaleX(0)';}
    iv=setInterval(function(){if(!done){t++;timer.textContent=fmt(t);if(t>=41)clearInterval(iv)}},1000);}
  function reset(){done=false;reveal.classList.remove('on');[].forEach.call(opts.children,function(b){b.disabled=false;b.classList.remove('ok','no')});run();}
  opts.addEventListener('click',function(e){
    var b=e.target.closest('.opt');if(!b||done)return;done=true;clearInterval(iv);
    var good=b.dataset.k==='c',ok=opts.querySelector('[data-k="c"]');
    [].forEach.call(opts.children,function(x){x.disabled=true});
    ok.classList.add('ok');if(!good)b.classList.add('no');
    bar.style.transition='none';
    verdict.textContent=good?'Correct. Twelve feet over a driveway, in '+fmt(t)+'.':"Not quite. It's 12 ft. 10 ft is the tempting pick, but that lower clearance doesn't apply over a driveway.";
    reveal.classList.add('on');
  });
  $('again').addEventListener('click',reset);
  run();
  /* fore-edge tabs follow the chapter in view */
  var links=[].slice.call(document.querySelectorAll('.tabs a'));
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(es){es.forEach(function(en){if(en.isIntersecting){links.forEach(function(a){a.classList.toggle('on',a.getAttribute('href')==='#'+en.target.id)})}})},{rootMargin:'-45% 0px -50% 0px'});
    ['answers','find','calcs','exam'].forEach(function(id){io.observe($(id))});
  }
})();

